function hmac(k,msg){if(k.length>64)k=sha256(k);const kk=new Uint8Array(64);kk.set(k);const ip=new Uint8Array(64+msg.length),op=new Uint8Array(96);for(let i=0;i<64;i++){ip[i]=kk[i]^0x36;op[i]=kk[i]^0x5c;}ip.set(msg,64);op.set(sha256(ip),64);return sha256(op);}
const b64u=s=>{s=String(s).replace(/-/g,'+').replace(/_/g,'/');const bin=atob(s+'==='.slice((s.length+3)%4));return Uint8Array.from(bin,ch=>ch.charCodeAt(0));};
